<script setup>
import {computed,onMounted,ref,watch} from 'vue';
import {brewApi} from '../api';
import {locationLabel} from '../location-label';
import ProductionPlanDetail from './ProductionPlanDetail.vue';
import JourneyDetailDialog from './JourneyDetailDialog.vue';
const category=ref('semi_finished'),factory=ref(''),keyword=ref(''),page=ref(1),data=ref({items:[],units:[],total:0,factories:[]}),loading=ref(false),error=ref(''),selectedPlan=ref(null),selected=ref(null),detail=ref(null),detailError=ref(''),detailLoading=ref(false);
let sequence=0,detailSequence=0;
const number=v=>Number(v||0).toLocaleString('zh-CN',{maximumFractionDigits:2});
const date=v=>v?String(v).slice(0,10):'—';
const status=row=>row.source_type==='production'&&row.tank_verified===false?'原液待核对':row.source_type==='production'?({fermenting:'发酵中',awaiting_packaging:'待包装',raw_ready:'酿造完成 · 在罐',in_tank:'生产中 · 在罐'}[row.production_status]||'原液在罐'):row.blocked>0?'部分受限':row.available>0?'可用':'已占用';
const availableReason=lot=>lot.frozen?'已冻结':lot.expiry_status==='expired'?'已过期':({qualified:'合格',pending:'待检',rejected:'不合格'}[lot.quality_status]||'待核查');
const metrics=computed(()=>data.value.units);
async function load(reset=false){if(reset)page.value=1;const id=++sequence;loading.value=true;error.value='';try{const result=await brewApi.browseStock({category:category.value,factory_id:factory.value,keyword:keyword.value,page:page.value,page_size:15});if(id===sequence)data.value=result;}catch(e){if(id===sequence)error.value=e.message;}finally{if(id===sequence)loading.value=false;}}
watch([category,factory],()=>load(true));
onMounted(()=>load());
async function open(row){if(row.source_type==='production'){selectedPlan.value=row.plan_id;return;}const id=++detailSequence;selected.value=row;detail.value=null;detailError.value='';detailLoading.value=true;try{const result=await brewApi.stockProduct(row.product.id,{factory_id:row.factory.id});if(id===detailSequence)detail.value=result;}catch(e){if(id===detailSequence)detailError.value=e.message;}finally{if(id===detailSequence)detailLoading.value=false;}}
function close(){++detailSequence;selected.value=null;}
</script>
<template>
<section class="factory-workspace">
<header class="fw-heading fw-compact-heading"><h2>酒液与成品库存</h2><form class="fw-search" @submit.prevent="load(true)"><input v-model.trim="keyword" type="search" aria-label="搜索库存" placeholder="搜索酒款、批次或罐位"><select v-if="data.factories.length>1" v-model="factory" aria-label="库存厂区"><option value="">全部厂区</option><option v-for="f in data.factories" :key="f.id" :value="f.id">{{ f.name }}</option></select><button class="btn btn-sm btn-outline" :disabled="loading">查询</button><button type="button" class="btn btn-sm btn-secondary" :disabled="loading" @click="load()">刷新</button></form></header>
<div class="fw-toolbar"><div class="fw-tabs" role="group" aria-label="库存类型"><button :class="{active:category==='semi_finished'}" @click="category='semi_finished'">原液 / 半成品</button><button :class="{active:category==='finished'}" @click="category='finished'">成品库存</button></div></div>
<div v-if="error" class="master-error" role="alert">{{ error }}</div>
<div v-for="u in metrics" :key="u.unit" class="fw-metrics"><div><small>{{ category==='semi_finished'?'酒液总量':'账面库存' }}</small><strong>{{ number(u.on_hand) }}<em>{{ u.unit }}</em></strong></div><div v-if="category==='semi_finished'"><small>生产在罐</small><strong class="highlight">{{ number(u.in_production) }}<em>{{ u.unit }}</em></strong></div><div><small>{{ category==='semi_finished'?'已入库可用':'可用库存' }}</small><strong class="highlight">{{ number(u.available) }}<em>{{ u.unit }}</em></strong></div><div v-if="u.reserved"><small>已占用</small><strong>{{ number(u.reserved) }}<em>{{ u.unit }}</em></strong></div><div v-if="u.estimated"><small>按计划估算 · 待实测</small><strong>{{ number(u.estimated) }}<em>{{ u.unit }}</em></strong></div></div>
<div class="fw-table-wrap"><table class="fw-table"><thead><tr><th>酒款 / 批次</th><th>{{ category==='semi_finished'?'罐位 / 厂区':'规格 / 厂区' }}</th><th class="fw-numeric">{{ category==='semi_finished'?'当前酒液量':'账面数量' }}</th><th class="fw-numeric">{{ category==='semi_finished'?'入库可用':'可用数量' }}</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="r in data.items" :key="[r.factory.id,r.product.id,r.batch_id].join('-')"><td><button class="fw-name" @click="open(r)">{{ r.product.name }}</button><small>{{ r.batch_name || r.lot_count+' 个批次' }}<template v-if="r.source_type==='production'"> · {{ r.plan_name }}</template></small></td><td><strong>{{ r.source_type==='production'?r.tank:r.product.specification || '—' }}</strong><small v-if="r.source_type==='production'&&r.tank_verified===false">计划罐位 · 实际位置待核对</small><small>{{ r.factory.name }}</small></td><td class="fw-numeric"><strong>{{ number(r.on_hand) }} <em>{{ r.product.unit }}</em></strong><small v-if="r.volume_basis==='planned'">计划估算</small></td><td class="fw-numeric"><span v-if="r.source_type==='production'" class="fw-muted">—</span><strong v-else>{{ number(r.available) }} <em>{{ r.product.unit }}</em></strong></td><td><span class="fw-status" :class="r.source_type==='production'?'in_progress':r.blocked>0?'warn':'done'">{{ status(r) }}</span><small v-if="r.earliest_expiration">最早到期 {{ date(r.earliest_expiration) }}</small></td><td><button class="fw-link" @click="open(r)">{{ r.source_type==='production'?'查看生产':'查看批次' }} →</button></td></tr></tbody></table><div v-if="!data.items.length" class="fw-empty">{{ loading?'正在加载库存…':'当前筛选下暂无库存' }}</div></div>
<footer class="fw-pagination"><span>共 {{ data.total }} 项<template v-if="category==='semi_finished'"> · 在罐原液需完成出酒入库后计入可用库存</template></span><div><button :disabled="page<=1||loading" @click="page--;load()">上一页</button><span>{{ page }} / {{ Math.max(1,Math.ceil(data.total/15)) }}</span><button :disabled="page*15>=data.total||loading" @click="page++;load()">下一页</button></div></footer>
<ProductionPlanDetail v-if="selectedPlan" :plan-id="selectedPlan" @close="selectedPlan=null" />
<JourneyDetailDialog v-if="selected" :title="selected.product.name" :subtitle="selected.factory.name+' · 库存批次'" @close="close"><div v-if="detailError" class="master-error">{{ detailError }}</div><p v-if="detailLoading" class="fw-detail-note">加载批次…</p><template v-else-if="detail"><div class="fw-table-wrap"><table class="fw-detail-table"><thead><tr><th>批次 / 库位</th><th>账面数量</th><th>可用数量</th><th>有效期</th><th>质量</th></tr></thead><tbody><tr v-for="lot in detail.lots" :key="lot.id"><td>{{ lot.name }}<small>{{ lot.locations.map(l=>locationLabel(l)).join(' / ') }}</small></td><td>{{ number(lot.on_hand) }} {{ lot.uom }}</td><td>{{ number(lot.available) }} {{ lot.uom }}</td><td>{{ date(lot.expiration_date) }}</td><td>{{ availableReason(lot) }}</td></tr></tbody></table></div><p v-if="!detail.lots?.length" class="fw-detail-note">暂无批次记录</p></template></JourneyDetailDialog>
</section>
</template>
<style src="../factory-workspace.css"></style>

<style scoped>
.fw-compact-heading{flex-wrap:wrap;gap:12px;margin-bottom:12px}.fw-compact-heading h2{margin:0;font-size:17px;white-space:nowrap}.fw-compact-heading .fw-search{margin-left:auto;align-items:center;flex-wrap:wrap}.fw-compact-heading :is(input,select,.btn){height:34px;min-height:34px;box-sizing:border-box;font-size:12px;padding:0 10px}.fw-compact-heading input{width:220px}.fw-compact-heading select{max-width:150px}.fw-toolbar{margin-bottom:16px}.fw-tabs button{padding:8px 0;margin-right:20px;border-bottom:2px solid transparent;border-radius:0}.fw-tabs button.active{background:none;border-color:var(--accent-gold)}.fw-metrics{gap:36px;padding-bottom:16px}.fw-metrics .highlight{color:var(--text-primary)}@media(max-width:760px){.fw-compact-heading .fw-search{width:100%}.fw-compact-heading input{flex:1;width:140px}}
</style>
